tools.example:
// Application Library: Acoustics_Module/Nonlinear_Acoustics/thermoacoustic_engine_heat_pump uses adiabatic and isothermal walls
model.component("comp1").physics("tatd").create("wall2", "Wall", 1);
model.component("comp1").physics("tatd").feature("wall2").selection().named("stack_walls");
model.component("comp1").physics("tatd").feature("wall2").set("ThermalCondition", "Adiabatic");

// Application Library: Acoustics_Module/Tutorials,_Thermoviscous_Acoustics/transfer_impedance_perforate
model.component("comp1").physics("ta").create("port1", "Port", 2);
model.component("comp1").physics("ta").feature("port1").selection().set(new int[]{3});
model.component("comp1").physics("ta").feature("port1").set("PortType", "PlaneWave");
model.component("comp1").physics("ta").feature("port1").set("PortExcitation", "on");
model.component("comp1").physics("ta").create("port2", "Port", 2);
// transfer impedance from ta.T11..ta.T22

// Application Library: Acoustics_Module/Tutorials,_Thermoviscous_Acoustics/pressure_reciprocity_calibration_coupler uses Velocity
model.component("comp1").physics("ta").create("velt1", "VelocityThermoacoustic", 1);
model.component("comp1").physics("ta").feature("velt1").selection().set(new int[]{5});
model.component("comp1").physics("ta").feature("velt1").set("u0", new String[]{"0", "v0"});
model.component("comp1").physics("ta").create("iso1", "Isothermal", 1);

// monopole convected by a uniform potential flow in 2D
model.component("comp1").physics("lpff").create("mfps1", "MassFlowPointSource", 0);
model.component("comp1").physics("lpff").feature("mfps1").selection().set(new int[]{5});

// Application Library: Acoustics_Module/Ultrasound/ultrasound_flow_meter_generic
model.component("comp1").physics().create("cwe", "ConvectedWaveEquation", "geom1");
// background flow from a k-omega CFD solution mapped with the Background Fluid Flow Coupling
model.component("comp1").multiphysics().create("bffc1", "BackgroundFluidFlowCoupling", 2);
model.component("comp1").multiphysics("bffc1").set("Source_physics", "spf");
model.component("comp1").multiphysics("bffc1").set("Destination_physics", "cwe");
model.component("comp1").physics("cwe").create("imp1", "AcousticImpedance", 1);
model.study("std2").create("time", "Transient");

// Application Library: Acoustics_Module/Ultrasound/hifu_tissue_sample
model.component("comp1").physics("nate").feature("natem1").create("mmp1", "MinMaxPressure", 2);
model.component("comp1").physics("nate").feature("natem1").feature("mmp1").selection().all();
// Results: Surface plot of nate.p_max at the last time step
